#!/usr/bin/env python3
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-02
"""
chunk-article.py

Deterministic finder-chunker for the proofread pipeline (Phase 1
plan: `chunk-article.py`). Splits a markdown article (PROOF_BASE) into windows a
finder agent can work over, first on `##` headings, then on paragraph
boundaries, packed greedily into windows of at most `proofread.chunkWords`
words (src/thresholds.json -- never inlined, per CLAUDE.md convention).

Every downstream change record (src/skills/proofread/references/
changes-schema.json) carries an absolute, 1-based `line` number in
PROOF_BASE, so this script's `startLine`/`endLine` are 1-based and absolute
in the *source* file, not relative to the chunk or the section.

Never-split guarantee: a fenced code block (``` or ~~~ ... closing fence), a
markdown table (a header row immediately followed by a `---`/`:--:`-style
separator row, plus its contiguous body rows), and a footnote definition
block (`[^id]: ...` through the next blank line) are each treated as one
atomic, indivisible unit. Packing may place an atomic unit alone in an
over-cap chunk rather than split it -- the cap is a best-effort target for
groupable prose paragraphs, not a hard ceiling that overrides the
never-split guarantee.

Usage:
    python3 chunk-article.py --input article.md [--thresholds thresholds.json]
                              [--chunk-words N]

--input          Path to the markdown PROOF_BASE file.
--thresholds     Path to thresholds.json (default: src/thresholds.json next
                  to this script's repo root). Read for
                  `proofread.chunkWords`.
--chunk-words    Override chunkWords directly (mainly for tests); skips
                  reading --thresholds when given.

Prints a JSON array of {id, heading, startLine, endLine, text} to stdout and
exits 0. Exits 2 on a missing/unreadable input file or a missing
`proofread.chunkWords` key with no --chunk-words override.

No third-party dependencies -- Python 3 standard library only.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
from typing import List, Optional

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
DEFAULT_THRESHOLDS_PATH = os.path.join(REPO_ROOT, "src", "thresholds.json")

FENCE_RE = re.compile(r"^\s*(```+|~~~+)")
HEADING_RE = re.compile(r"^##\s+(.*\S)\s*$")
FOOTNOTE_DEF_RE = re.compile(r"^\[\^[^\]]+\]:")
TABLE_SEPARATOR_RE = re.compile(r"^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)+\|?\s*$")


class Block:
    """One indivisible-or-not content unit between chunk-packing decisions."""

    __slots__ = ("heading", "start_line", "end_line", "atomic", "word_count")

    def __init__(self, heading: Optional[str], start_line: int, end_line: int, atomic: bool, word_count: int):
        self.heading = heading
        self.start_line = start_line
        self.end_line = end_line
        self.atomic = atomic
        self.word_count = word_count


def _word_count(lines: List[str]) -> int:
    return sum(len(line.split()) for line in lines)


def _looks_like_table_row(line: str) -> bool:
    return "|" in line and line.strip() != ""


def parse_blocks(lines: List[str]) -> List[Block]:
    """Walk 1-indexed source lines, emitting Block objects in source order.

    `lines` is the 0-indexed list from str.splitlines(); a block's
    start_line/end_line are 1-based and inclusive, matching the schema's
    `line` convention.
    """
    blocks: List[Block] = []
    n = len(lines)
    i = 0  # 0-based index into `lines`
    current_heading: Optional[str] = None

    while i < n:
        line = lines[i]

        # Blank line: paragraph separator only, never a block of its own.
        if line.strip() == "":
            i += 1
            continue

        # Heading: updates current_heading, consumes one line, no block.
        heading_match = HEADING_RE.match(line)
        if heading_match:
            current_heading = heading_match.group(1)
            i += 1
            continue

        # Fenced code block: atomic, from opening fence to matching close
        # (or EOF if unterminated -- better to swallow the rest than guess).
        fence_match = FENCE_RE.match(line)
        if fence_match:
            fence_token = fence_match.group(1)[0] * 3
            start = i
            i += 1
            while i < n and not lines[i].strip().startswith(fence_token):
                i += 1
            if i < n:
                i += 1  # include the closing fence line
            end = i - 1
            blocks.append(Block(current_heading, start + 1, end + 1, True, _word_count(lines[start : end + 1])))
            continue

        # Footnote definition: atomic, from `[^id]:` through the line before
        # the next blank line (or EOF).
        if FOOTNOTE_DEF_RE.match(line):
            start = i
            i += 1
            while i < n and lines[i].strip() != "":
                i += 1
            end = i - 1
            blocks.append(Block(current_heading, start + 1, end + 1, True, _word_count(lines[start : end + 1])))
            continue

        # Table: a row followed immediately by a separator row starts a
        # table block; consume contiguous rows containing '|' after that.
        if (
            "|" in line
            and i + 1 < n
            and TABLE_SEPARATOR_RE.match(lines[i + 1])
        ):
            start = i
            i += 2  # header + separator
            while i < n and _looks_like_table_row(lines[i]):
                i += 1
            end = i - 1
            blocks.append(Block(current_heading, start + 1, end + 1, True, _word_count(lines[start : end + 1])))
            continue

        # Regular paragraph: consume until blank line, heading, fence,
        # footnote definition, or table start.
        start = i
        i += 1
        while i < n:
            nxt = lines[i]
            if nxt.strip() == "":
                break
            if HEADING_RE.match(nxt):
                break
            if FENCE_RE.match(nxt):
                break
            if FOOTNOTE_DEF_RE.match(nxt):
                break
            if "|" in nxt and i + 1 < n and TABLE_SEPARATOR_RE.match(lines[i + 1]):
                break
            i += 1
        end = i - 1
        blocks.append(Block(current_heading, start + 1, end + 1, False, _word_count(lines[start : end + 1])))

    return blocks


def pack_chunks(blocks: List[Block], source_lines: List[str], chunk_words: int) -> List[dict]:
    """Group consecutive same-heading blocks into <=chunk_words windows.

    A heading change always starts a new chunk (never merges blocks from two
    different `##` sections into one window), matching "first on headings,
    then on paragraph boundaries".
    """
    chunks: List[dict] = []
    current: List[Block] = []
    current_words = 0
    current_heading: object = "__unset__"  # sentinel, distinct from None

    def flush():
        nonlocal current, current_words
        if not current:
            return
        start_line = current[0].start_line
        end_line = current[-1].end_line
        text = "\n".join(source_lines[start_line - 1 : end_line])
        chunks.append(
            {
                "id": f"chunk-{len(chunks) + 1:03d}",
                "heading": current[0].heading,
                "startLine": start_line,
                "endLine": end_line,
                "text": text,
            }
        )
        current = []
        current_words = 0

    for block in blocks:
        if block.heading != current_heading:
            flush()
            current_heading = block.heading

        if current and current_words + block.word_count > chunk_words:
            flush()

        current.append(block)
        current_words += block.word_count

    flush()
    return chunks


def _load_chunk_words(thresholds_path: str) -> int:
    with open(thresholds_path, encoding="utf-8") as fh:
        data = json.load(fh)
    try:
        return int(data["proofread"]["chunkWords"])
    except (KeyError, TypeError, ValueError) as exc:
        raise KeyError("thresholds.json missing proofread.chunkWords") from exc


def chunk_article(text: str, chunk_words: int) -> List[dict]:
    lines = text.splitlines()
    blocks = parse_blocks(lines)
    return pack_chunks(blocks, lines, chunk_words)


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Split a markdown article into finder chunks with absolute line offsets.",
    )
    parser.add_argument("--input", required=True, help="Path to the PROOF_BASE markdown file.")
    parser.add_argument(
        "--thresholds",
        default=DEFAULT_THRESHOLDS_PATH,
        help="Path to thresholds.json (default: src/thresholds.json).",
    )
    parser.add_argument(
        "--chunk-words",
        type=int,
        default=None,
        help="Override proofread.chunkWords directly (skips reading --thresholds).",
    )
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    try:
        with open(args.input, encoding="utf-8") as fh:
            text = fh.read()
    except OSError as exc:
        print(f"chunk-article.py: cannot read --input: {exc}", file=sys.stderr)
        return 2

    if args.chunk_words is not None:
        chunk_words = args.chunk_words
    else:
        try:
            chunk_words = _load_chunk_words(args.thresholds)
        except (OSError, json.JSONDecodeError, KeyError) as exc:
            print(f"chunk-article.py: {exc}", file=sys.stderr)
            return 2

    chunks = chunk_article(text, chunk_words)
    print(json.dumps(chunks, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())
